fn main() {
    let poem = "\
Night falls on the library.
The owl on the shelf opens one eye.
Owls read in silence, one page a night.
A mouse borrows a crumb and a light.
Who stamps the books when nobody is there?
The owl, of course. She takes great care.";
    let query = "the";
    let mut found = 0;
    let mut n = 0;
    for line in poem.lines() {
        n += 1;
        let hit = line.contains(query);
        if hit {
            found += 1;
        }
        println!("{n} {hit} {found}");
    }
}
